use bloom_filter::BloomFilter;

#[test]
fn test_inserted_items_found() {
    let mut bf = BloomFilter::new(1000);
    bf.insert("hello");
    bf.insert("world");
    bf.insert("rust");
    assert!(bf.might_contain("hello"));
    assert!(bf.might_contain("world"));
    assert!(bf.might_contain("rust"));
}

#[test]
fn test_absent_item_usually_not_found() {
    let mut bf = BloomFilter::new(1000);
    bf.insert("abc");
    // 'xyz' was never inserted; with size=1000 and k=3, false positive rate is very low
    // This may occasionally fail but probability < 0.001 with these params
    assert!(!bf.might_contain("xyz"));
}

#[test]
fn test_empty_filter() {
    let bf = BloomFilter::new(256);
    assert!(!bf.might_contain("anything"));
}
